using System.Xml.Serialization;
namespace Clc.Polaris.Api.UnitTests.SerializationAndModels.Xml.Deserialization { [TestClass][UnitTest] public sealed class ILLRequestResultTests { [TestMethod] public void Deserialize_SuccessWithTxnGroupQualifer() { var r = Deserialize<ILLRequestResult>("<ILLRequestResult><RequestGUID>g</RequestGUID><TxnGroupQualifer>tg</TxnGroupQualifer><TxnQualifier>tq</TxnQualifier><StatusType>s</StatusType><StatusValue>v</StatusValue><Message>m</Message></ILLRequestResult>"); Assert.IsNull(r.PAPIErrorCode); Assert.AreEqual("tg", r.TxnGroupQualifer); Assert.AreEqual("tg", r.TxnGroupQualifier); } [TestMethod] public void Deserialize_Failure() { var r = Deserialize<ILLRequestResult>("<ILLRequestResult><PAPIErrorCode>1</PAPIErrorCode><ErrorMessage>bad</ErrorMessage></ILLRequestResult>"); Assert.AreEqual(1, r.PAPIErrorCode); Assert.AreEqual("bad", r.ErrorMessage); } private static T Deserialize<T>(string xml) { using var reader = new StringReader(xml); return (T)new XmlSerializer(typeof(T)).Deserialize(reader)!; } } }
